import {beginStep,advanceStep} from './movement.js?v=0.87.0';
// Newly authored optional flavour. These are villagers' beliefs, not a neutral account of the war.
const definitions={
 dorelem:[{id:'keep-civilian',label:'Dorelem resident',civilian:2,route:[[14,20],[16,20],[16,22],[14,22]],talk:['A wall keeps people out. It does not tell you whether they should have been kept out.','The passage below the keep was built for supplies. These days it carries families as often as barrels.']}],
 philomere:[{id:'patient-family',label:'Patient’s relative',civilian:0,route:[[15,20],[17,20],[17,22],[15,22]],talk:['My brother fought under the True Light. The nurse who saved him wears Dawn Bloom colours.','We need medicine and time. Neither army seems inclined to leave us much of either.']}],
 pate:[{id:'pate-mother',label:'Pate’s mother',civilian:0,route:[[20,18],[20,20],[22,20],[22,18]],talk:['Pate left before dawn. He barely touched his breakfast. He had already claimed a real Abyssal; I thought he had told you.','He spoke so proudly of marching under the Light. I was proud too. It is easier to be proud before the door closes.']},{id:'pate-father',label:'Pate’s father',civilian:1,route:[[28,18],[30,18],[30,20],[28,20]],talk:['Your friend was forever talking about the day he would join the crusade. Now his chair is empty.','Walter blessed the column before it left. I have to believe the Church knows what it is asking of our children.']}],
 trade:[{id:'trade-mother',label:'Trade’s mother',civilian:0,route:[[20,16],[20,18],[18,18],[18,16]],talk:['Trade was up before the bells. He left something for you with his grandfather. Go and speak to him.','Trade always sounds certain once a decision is made. It does not mean leaving was easy.']},{id:'trade-grandfather',label:'Trade’s grandfather',civilian:3,route:[[28,20],[30,20],[30,22],[28,22]],talk:['Trade and Pate went together. That is something to be thankful for, even if you wish they had waited.','The whole village is speaking of duty today. It is a grand word until someone you love has to walk away.']}],
 town:[{id:'church-devotee',label:'Church devotee',civilian:3,route:[[31,11],[33,11],[33,12],[31,12]],talk:['The True Light gives this village its purpose. Without the Church, we would be scattered households looking after nobody but ourselves.','The Church says this crusade will defend our people and carry the Light beyond our banners. I trust its judgement.','Those who reject the Light will not leave us in peace simply because we ask politely. Better our soldiers stand together than our families stand alone.']},{id:'banner-weaver',label:'Banner weaver',civilian:2,route:[[16,17],[18,17],[18,19],[16,19]],talk:['Ivory and blue. I stitched until my fingers ached, and I would do it again. Our soldiers should know the whole village stands behind them.','They call the crusade harsh. What is harsh about defending the faith that holds us together?','I have never met anyone from the other side. I have heard enough at the shrine to know which banner I would rather live beneath.']},{id:'supply-carrier',label:'Supply carrier',civilian:1,route:[[13,22],[15,22],[15,25],[13,25]],talk:['Bread, bandages, boots. A crusade is not only won by the people carrying swords. Every household ought to do its part.','The Church has called, so we answer. If the other side had respected the True Light, perhaps there would be no need for all this.','Keep your supplies stocked. Righteousness will not mend a split boot or fill an empty stomach.']},{id:'muster-supporter',label:'Muster supporter',civilian:0,route:[[40,21],[42,21],[42,23],[40,23]],talk:['I watched the column leave this morning. Such fine banners. Such brave faces. The Light must surely be with them.','People beyond our faith cannot be allowed to decide how our children live. That is why I support the crusade.','Some say we should listen to their side. I say they can listen when they stop opposing the Church.']}]
};
export function createResidents(room){return (definitions[room]||[]).map((n,i)=>({...n,resident:true,x:n.route[0][0],y:n.route[0][1],px:n.route[0][0]*16+8,py:n.route[0][1]*16+8,facing:'down',step:null,stride:0,moving:false,next:1,wait:.6+i*.35}));}
export function residentBlocks(n,x,y){return n.x===x&&n.y===y||n.step?.x===x&&n.step?.y===y;}
export function updateResidents(list,dt,solid,player){for(const n of list){if(n.step){advanceStep(n,dt);if(!n.step&&n.x===n.route[n.next][0]&&n.y===n.route[n.next][1]){n.next=(n.next+1)%n.route.length;n.wait=.8;}continue;}n.wait-=dt;if(n.wait>0)continue;const [tx,ty]=n.route[n.next];const x=n.x+Math.sign(tx-n.x),y=x===n.x?n.y+Math.sign(ty-n.y):n.y;if(x===n.x&&y===n.y){n.next=(n.next+1)%n.route.length;continue;}if(solid(x,y)||list.some(other=>other!==n&&residentBlocks(other,x,y))||player.x===x&&player.y===y||player.step?.x===x&&player.step?.y===y){n.wait=.3;continue;}n.facing=x>n.x?'right':x<n.x?'left':y>n.y?'down':'up';beginStep(n,x,y,.4);}}
